export type CheckReport = Readonly<{
    schemaVersion: 1;
    outcome: "passed";
    diagnostics: readonly [
    ];
    packageChanges: readonly PackageChange[];
}> | Readonly<{
    schemaVersion: 1;
    outcome: "rejected";
    diagnostics: readonly Diagnostic[];
    packageChanges: readonly PackageChange[];
}>;

export type ConsumptionEffect = Readonly<{
    kind: "remove";
}> | Readonly<{
    kind: "record";
    evidencePath: string;
}>;

export type Diagnostic = Readonly<{
    code: DiagnosticCode;
    packageName?: string;
    path?: string;
    intentId?: string;
    message: string;
}>;

export type ExpectedInputs = Readonly<{
    binding: InputBinding;
    packages: readonly WorkspacePackage[];
    intents: readonly ReleaseIntent[];
    plan: Readonly<{
        releases: readonly PlannedRelease[];
        consumptions: readonly PlannedConsumption[];
    }>;
    permittedChanges: readonly PermittedChange[];
}>;

export type FileChange = Readonly<{
    path: string;
    classification: string;
    kind: ChangeKind;
    before: FileLeaf | null;
    after: FileLeaf | null;
}>;

export type FileLeaf = LeafShape & Readonly<{
    digest: string;
}>;

export type InputBinding = Readonly<{
    source: Readonly<{
        repository: string;
        identity: string;
        digest: string;
    }>;
    engine: Readonly<{
        name: string;
        version: string;
        digest: string;
    }>;
    configDigest: string;
    inventoryDigest: string;
    policyDigest: string;
    intentsDigest: string;
    planDigest: string;
}>;

export type JsonRecord = {
    readonly [key: string]: Json;
};

export type LeafShape = Readonly<{
    type: "file";
    mode: "100644" | "100755";
}> | Readonly<{
    type: "symlink";
    mode: "120000";
}> | Readonly<{
    type: "gitlink";
    mode: "160000";
}>;

export type ManifestSnapshot = Readonly<{
    file: FileLeaf;
    semantic: JsonRecord;
}>;

export type ObservedCandidate = Readonly<{
    binding: InputBinding;
    candidateIdentity: string;
    manifests: readonly ObservedManifest[];
    consumptions: readonly ObservedConsumption[];
    diff: readonly FileChange[];
}>;

export type ObservedConsumption = Readonly<{
    intentId: string;
    digest: string;
    effect: ConsumptionEffect;
}>;

export type ObservedManifest = Readonly<{
    manifestPath: string;
    before: ManifestSnapshot | null;
    after: ManifestSnapshot | null;
}>;

export type PackageChange = Readonly<{
    packageName: string;
    manifestPath: string;
    oldVersion: string | null;
    newVersion: string | null;
}>;

export type PermittedChange = Readonly<{
    path: string;
    classification: string;
    kind: ChangeKind;
    before: LeafShape | null;
    after: LeafShape | null;
    contentAuthority: string;
}>;

export type PlannedConsumption = Readonly<{
    intentId: string;
    effect: ConsumptionEffect;
}>;

export type PlannedRelease = Readonly<{
    packageName: string;
    manifestPath: string;
    type: ReleaseType | "none";
    oldVersion: string | null;
    newVersion: string | null;
    intentIds: readonly string[];
}>;

export type ReleaseCandidateInput = Readonly<{
    schemaVersion: 1;
    expected: ExpectedInputs;
    observed: ObservedCandidate;
}>;

export type ReleaseIntent = Readonly<{
    id: string;
    path: string;
    digest: string;
    participation: "pending" | "retained";
    requests: readonly Readonly<{
        packageName: string;
        type: ReleaseType;
    }>[];
}>;

export type WorkspacePackage = Readonly<{
    name: string;
    root: string;
    manifestPath: string;
    classification: "public" | "private";
    versioning: "versioned" | "unversioned" | "ignored";
    before: ManifestSnapshot;
}>;

export type ConformanceCase = Readonly<{
    id: string;
    input: unknown;
    expected: Readonly<{
        outcome: "passed" | "rejected";
        diagnosticCodes: readonly DiagnosticCode[];
        packageChanges: readonly PackageChange[];
    }>;
}>;

export type PackageChange = Readonly<{
    packageName: string;
    manifestPath: string;
    oldVersion: string | null;
    newVersion: string | null;
}>;
